// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_supportsTokenCheck(address caller) public {
        vm.assume(caller != address(c));
        vm.assume(caller != address(0));

        // Ensure caller has no balance before the test
        vm.prank(caller);
        bool reverted = false;
        try c.airDrop() {
            // If it succeeds, caller must have had tokenBalance == 0 AND supportsToken passed
            // supportsToken passes only if msg.sender is a Bank contract returning the correct hash
            // Since caller is a random address (not a Bank contract), it should revert
            reverted = false;
        } catch {
            reverted = true;
        }

        // The rule: For any caller that is not a Bank contract, airDrop() should revert
        assertTrue(reverted);
    }
}

